# Mother Claude foreign-control hook helper, Windows. Generated by the Mother
# Claude desktop app; do not edit (it is rewritten on every start).
#
#   powershell.exe ... -File mc-hook.ps1 <event> <max-seconds> <observe|decide>
#                                                             (exec-form hook)
#
# The Windows twin of mc-hook. Forwards the hook payload on stdin to the
# Mother Claude app over loopback. In "decide" mode it prints the app's JSON
# answer. It never fails the hook: whatever happens (app closed, token
# rotated, control turned off) it exits 0, and it prints nothing unless the
# app answered with a 2xx. The payload and the answer pass through as bytes,
# never re-encoded.

$ErrorActionPreference = 'Stop'
$McData = '@MC_DATA@'

# One process: its name and its parent's id, or $null once it is gone.
function Get-Proc([int]$Id) {
    $q = New-Object System.Management.ManagementObjectSearcher(
        "SELECT Name, ParentProcessId FROM Win32_Process WHERE ProcessId=$Id")
    foreach ($p in $q.Get()) {
        return @{ Name = ([string]$p['Name']).ToLowerInvariant(); Parent = [int]$p['ParentProcessId'] }
    }
    return $null
}

# The Claude Code process: the first ancestor that is not a shell (an
# exec-form hook's parent is the CLI itself).
function Get-ClaudePid {
    $me = Get-Proc $PID
    if (-not $me) { return 0 }
    $id = $me.Parent
    for ($i = 0; $i -lt 6; $i++) {
        if ($id -le 4) { return 0 }
        $p = Get-Proc $id
        if (-not $p) { return 0 }
        if (@('cmd.exe', 'powershell.exe', 'pwsh.exe') -notcontains $p.Name) { return $id }
        $id = $p.Parent
    }
    return 0
}

# hook.base and the token of hook.curlrc, or $null when either is missing or
# not what the app writes (a loopback base, one bearer header).
function Read-AppConf([string]$Dir) {
    $rc = Join-Path $Dir 'hook.curlrc'
    $bf = Join-Path $Dir 'hook.base'
    if (-not (Test-Path -LiteralPath $rc -PathType Leaf) -or
        -not (Test-Path -LiteralPath $bf -PathType Leaf)) { return $null }
    $base = [string](Get-Content -LiteralPath $bf -TotalCount 1)
    if ($base -cnotmatch '^http://127\.0\.0\.1:[0-9]+\z') { return $null }
    $auth = ''
    foreach ($line in @(Get-Content -LiteralPath $rc)) {
        if ($line -cmatch '^header = "Authorization: (Bearer [A-Za-z0-9_-]+)"\s*\z') { $auth = $Matches[1] }
    }
    if (-not $auth) { return $null }
    return @{ Base = $base; Auth = $auth }
}

# POST the bytes to the app. Code 0: nothing answered.
function Send-ToApp([string]$Url, [byte[]]$Body, [int]$Seconds, [string]$Auth, [string]$CliPid, [string]$Account) {
    $req = [System.Net.HttpWebRequest][System.Net.WebRequest]::Create($Url)
    $req.Method = 'POST'
    $req.Proxy = $null
    $req.KeepAlive = $false
    $req.ServicePoint.Expect100Continue = $false
    $req.Timeout = $Seconds * 1000
    $req.ReadWriteTimeout = $Seconds * 1000
    $req.ContentType = 'application/json'
    $req.Headers.Add('Authorization', $Auth)
    if ($CliPid) { $req.Headers.Add('X-MC-Pid', $CliPid) }
    if ($Account) { $req.Headers.Add('X-MC-Token-Sha256', $Account) }
    $req.ContentLength = $Body.Length
    $s = $req.GetRequestStream()
    $s.Write($Body, 0, $Body.Length)
    $s.Close()
    try {
        $resp = $req.GetResponse()
    } catch [System.Net.WebException] {
        $resp = $_.Exception.Response
        if (-not $resp) { return @{ Code = 0; Body = $null } }
    }
    $buf = New-Object System.IO.MemoryStream
    $rs = $resp.GetResponseStream()
    if ($rs) { $rs.CopyTo($buf) }
    $code = [int]$resp.StatusCode
    $resp.Close()
    return @{ Code = $code; Body = $buf.ToArray() }
}

try {
    # Read the payload first, whatever happens next: the CLI is writing it.
    $in = New-Object System.IO.MemoryStream
    [Console]::OpenStandardInput().CopyTo($in)

    # Sessions Mother Claude runs itself report through their own channel.
    if ($env:MOTHER_CLAUDE_OWNED -eq '1') { exit 0 }
    if (-not (Test-Path -LiteralPath $McData -PathType Container) -and $env:CLAUDE_PLUGIN_ROOT) {
        $McData = Join-Path $env:CLAUDE_PLUGIN_ROOT '..\..'
    }
    if (Test-Path -LiteralPath (Join-Path $McData 'hook.disabled')) { exit 0 }
    $conf = Read-AppConf $McData
    if (-not $conf) { exit 0 }

    $max = 2
    if ($args.Count -ge 2 -and [string]$args[1] -cmatch '^[0-9]{1,7}\z') {
        $max = [Math]::Min([Math]::Max([int]$args[1], 1), 86400)
    }
    $mode = 'observe'
    if ($args.Count -ge 3) { $mode = [string]$args[2] }

    # A session run with a long-lived token (a Mother Claude token account):
    # send only the token's SHA-256, so the app can tell which account it is.
    # The token itself never leaves this process.
    $acct = ''
    $token = [string]$env:CLAUDE_CODE_OAUTH_TOKEN
    if ($token) {
        $sha = [System.Security.Cryptography.SHA256]::Create()
        $acct = -join ($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($token)) |
            ForEach-Object { $_.ToString('x2') })
    }

    $cli = ''
    try {
        $p = Get-ClaudePid
        if ($p -gt 1) { $cli = [string]$p }
    } catch {}

    $r = Send-ToApp "$($conf.Base)/hooks/event" $in.ToArray() $max $conf.Auth $cli $acct
    if ($r.Code -ge 200 -and $r.Code -lt 300 -and $mode -ne 'observe' -and $r.Body.Length -gt 0) {
        $o = [Console]::OpenStandardOutput()
        $o.Write($r.Body, 0, $r.Body.Length)
        $o.Flush()
    }
} catch {}
exit 0
